/* Self-contained design prototype. All records and effects are synthetic and stay in memory. */
const $ = (selector) => document.querySelector(selector);
const escape = (value) => String(value).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json = (value) => `<pre>${escape(JSON.stringify(value, null, 2))}</pre>`;
const state = { route: 'runs', scenario: 'normal', node: 'qa', inspector: 'Overview', run: 'running', agent: 'Developer', agentTab: 'Chain', configStep: 1, configMode: 'Guided', model: 'example-coding-model', provider: 'codex_cli', approved: false, memory: 'Facts', connected: new Set(['Codex CLI', 'GitHub']), disabledTools: new Set(), notification: false };
const agents = [
  ['PM','Requirements & acceptance','PM'],['Designer','Interaction & visual design','DS'],['Developer','Architecture & implementation','DV'],['QA','Reproduction & verification','QA'],['Manager','Coordination & independent review','MG'],['DevOps','Environment & delivery','DO'],['CISO','Risk & security evidence','CS']
];
const steps = {
  Developer: [['Load approved scope','Resolve task, source commit and relevant memory.','CODE'],['Inspect and implement','Use authorized source tools within the task boundary.','AGENT'],['Check the change','Run registered checks against the changed snapshot.','CODE'],['Return evidence','Submit changed files, observations and unresolved issues.','AGENT']],
  PM: [['Read repository brief','Read indexed source references and user outcome.','CODE'],['Define acceptance','Write bounded requirements and unresolved questions.','AGENT'],['Validate scope','Check task dependencies, limits and required inputs.','CODE']],
  Designer: [['Inspect product context','Read existing components, tokens and constraints.','CODE'],['Design interaction','Propose screens, states and acceptance evidence.','AGENT'],['Request design review','Ask the operator to review material visual decisions.','HUMAN']],
  QA: [['Load verification snapshot','Use the approved source snapshot and registered commands.','CODE'],['Run checks','Execute tests without modifying verification policy.','CODE'],['Assess acceptance','Report passed, failed and unverified criteria.','AGENT']],
  Manager: [['Coordinate plan','Assign tasks using declared roles and dependencies.','AGENT'],['Isolate review context','Start a separate review invocation with diff and evidence.','CODE'],['Judge delivery','Evaluate acceptance with independent context.','AGENT'],['Enforce gates','Require every mandatory check before publication.','CODE']],
  DevOps: [['Inspect build contract','Resolve lockfiles, runtime and CI requirements.','CODE'],['Prepare delivery','Produce a release candidate and changelog from evidence.','AGENT'],['Verify candidate','Check exact commit, checksums and terminal CI results.','CODE'],['Authorize release','Publication needs a separate operator decision.','HUMAN']],
  CISO: [['Collect findings','Run pinned security checks against the candidate.','CODE'],['Assess applicability','Explain impact, evidence and remediation.','AGENT'],['Enforce security policy','Unresolved blocking findings stop delivery.','CODE']]
};
const nodes = {
  intake:{title:'Preflight',agent:'System',kind:'CODE',status:'completed',time:'0.8 s',detail:'Configuration, repository access and permissions checked.',tool:'validate_run',tokens:null},
  pm:{title:'Define acceptance',agent:'PM',kind:'AGENT',status:'completed',time:'24 s',detail:'Scoped the fix to empty checkout input and retained the existing API.',tool:'read_context',tokens:3200},
  developer:{title:'Fix input validation',agent:'Developer',kind:'AGENT',status:'completed',time:'2m 08s',detail:'Added an explicit empty-input branch and a regression case.',tool:'edit_source',tokens:12480},
  qa:{title:'Verify regression',agent:'QA',kind:'CODE',status:'running',time:'42 s',detail:'Running registered checks on snapshot 8f20c1e. No completion recorded yet.',tool:'execute',tokens:null},
  ciso:{title:'Security checks',agent:'CISO',kind:'AGENT',status:'pending',time:'—',detail:'Waiting for the verified implementation snapshot.',tool:'scan_snapshot',tokens:null},
  manager:{title:'Independent review',agent:'Manager',kind:'AGENT',status:'pending',time:'—',detail:'A separate invocation will inspect the diff and verification evidence.',tool:'read_evidence',tokens:null},
  delivery:{title:'Create draft PR',agent:'DevOps',kind:'CODE',status:'pending',time:'—',detail:'Publication requires successful checks and the launch permission.',tool:'publish_draft_pr',tokens:null},
  release:{title:'Release approval',agent:'Operator',kind:'HUMAN',status:'pending',time:'—',detail:'Separate optional operation. No release is authorized by this run.',tool:null,tokens:null}
};
function tag(text, color=''){return `<span class="tag ${color}">${escape(text)}</span>`;}
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${action}</div></div>`;}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function tabButtons(values,selected,attribute){return `<div class="tabs">${values.map(v=>`<button ${attribute}="${escape(v)}" aria-pressed="${selected===v}">${escape(v)}</button>`).join('')}</div>`;}
function emptyView(title,description,route){return `<div class="empty"><div class="eyebrow">NOTHING HERE YET</div><h2>${title}</h2><p>${description}</p><a class="button-link" href="#${route}">Open ${route}</a></div>`;}
function node(id){const n=nodes[id]; const status=id==='qa'&&state.run!=='running'?state.run:n.status;return `<button class="flow-node ${n.kind==='CODE'?'code':n.kind==='HUMAN'?'human':''} ${n.status==='pending'?'pending':''} ${state.node===id?'selected':''}" data-node="${id}" aria-pressed="${state.node===id}"><span class="flow-node-top"><span>${n.agent} · ${n.kind}</span><span>${status==='completed'?'✓':status==='running'?'●':status==='pending'?'○':'Ⅱ'} ${n.time}</span></span><strong>${n.title}</strong><small>${status==='completed'?'Completed':status==='pending'?'Not started':status==='running'?'In progress':escape(status)}</small></button>`;}
function inspector(){const n=nodes[state.node];return `<header><h2>Step inspector</h2>${tag(n.kind,n.kind==='CODE'?'green':n.kind==='HUMAN'?'amber':'blue')}</header><h2>${n.title}</h2><p style="font-size:12px">${n.detail}</p>${tabButtons(['Overview','JSON','Evidence'],state.inspector,'data-inspector')}${state.inspector==='JSON'?json({version:1,type:'step.status',run_id:'demo-run-042',step_id:state.node,attempt:1,sender:n.agent,recipient:'Manager',correlation_id:`demo-${state.node}-01`,payload:{status:n.status,tool:n.tool,recorded_tokens:n.tokens}}):state.inspector==='Evidence'?`<div class="message"><strong>Source snapshot</strong><p><code>8f20c1e · checkout-service</code><br>All references on this screen are synthetic.</p></div>${n.status==='pending'?'<p>No evidence exists for a step that has not run.</p>':`<ul class="checklist"><li>Commit provenance ${tag('Recorded','green')}</li><li>Verification output ${tag(n.status==='completed'?'Available':'Pending',n.status==='completed'?'green':'amber')}</li><li>Artifact <code>demo/checks.json</code></li></ul>`}`:`<dl class="kv"><dt>Agent</dt><dd>${n.agent}</dd><dt>Model</dt><dd>${n.kind==='AGENT'?'example-coding-model':'Deterministic step'}</dd><dt>Status</dt><dd>${n.status}</dd><dt>Attempt</dt><dd>1 of 3 maximum</dd><dt>Tokens</dt><dd>${n.tokens===null?'Not applicable / not recorded':n.tokens.toLocaleString('en-US')}</dd><dt>Tool</dt><dd><code>${n.tool||'None'}</code></dd></dl><div class="message"><strong>Developer → QA</strong><p>“The empty-input case is now explicit. Verify the regression and existing checkout behavior against this snapshot.”</p></div><div class="footer-note">Recorded handoff, not hidden model reasoning.</div>`}`;}
function runs(){return timelineRunView();}
function agentContent(){const name=state.agent;const role=agents.find(a=>a[0]===name);const tab=state.agentTab;let body='';
  if(tab==='Chain')body=`<p>The procedure belongs to this specialist. The factory flow decides when to invoke it.</p><div class="stack">${steps[name].map((s,i)=>`<div class="chain-step"><span class="mono">${String(i+1).padStart(2,'0')}</span><div><strong>${s[0]}</strong><p>${s[1]}</p></div>${tag(s[2],s[2]==='CODE'?'green':s[2]==='HUMAN'?'amber':'blue')}</div>`).join('')}</div><p class="footer-note">Registered steps only. Editing this draft cannot alter an active run or grant tools.</p>`;
  if(tab==='Overview')body=`<div class="two-col"><div><h3>Responsibility</h3><p>${role[1]}. Deliver typed results and cite evidence for every completion claim.</p><h3>Execution</h3><p>Local specialist · Codex CLI<br>Model inherited from factory configuration.</p></div><div><h3>Boundaries</h3><ul class="checklist"><li>Project-scoped context ${tag('Required','green')}</li><li>Independent verification ${tag('Enforced','green')}</li><li>Grant new permissions ${tag('Not allowed')}</li></ul></div></div>`;
  if(tab==='Instructions & skills')body=`<label class="field">Draft instructions<textarea class="agent-prompt">Work within the approved scope. Inspect source evidence before acting. Use registered tools only. Report unresolved issues explicitly. Never weaken verification to obtain a passing result.</textarea></label><h3 style="margin-top:24px">Attached skills</h3><div class="pill-line">${tag('engineering · v3')}${tag('verification · v2')}${tag('repository conventions · v1')}</div><p class="footer-note">Skills guide behavior. They do not grant permissions.</p><button data-action="draft">Save draft</button>`;
  if(tab==='Tools')body=`<p>Effective access is the intersection of agent, project and run permissions.</p><ul class="checklist">${['read_file','search_source','read_memory','execute'].map(t=>`<li><code>${t}</code>${tag('Allowed','green')}</li>`).join('')}<li><code>publish_release</code>${tag('Separate approval','amber')}</li></ul><a class="button-link" href="#tools" style="margin-top:20px">Manage tool connections</a>`;
  if(tab==='Context')body=`<div class="metrics"><div class="metric"><span>Memory items</span><strong>4 max</strong></div><div class="metric"><span>Memory excerpt budget</span><strong>6 KiB</strong></div><div class="metric"><span>Scope</span><strong>Project</strong></div></div><p>Retrieve relevant source excerpts and verified facts. Preserve provenance through compaction and load additional evidence on demand.</p><a class="button-link" href="#memory">Inspect project memory</a>`;
  if(tab==='Versions')body=`<table><thead><tr><th>VERSION</th><th>STATE</th><th>CHANGES</th></tr></thead><tbody><tr><td>v4</td><td>${tag('Draft','amber')}</td><td>Clarify acceptance handoff</td></tr><tr><td>v3</td><td>${tag('Published','green')}</td><td>Bound context and tool permissions</td></tr><tr><td>v2</td><td>Archived</td><td>Initial registered procedure</td></tr></tbody></table><p class="footer-note">Run 042 retains v3. Publishing v4 only affects future launches.</p><button data-action="publish-agent">Review version changes</button>`;
  return `<div class="section-head"><div><div class="eyebrow">LOCAL SPECIALIST / V3 PUBLISHED</div><h2>${name==='Manager'?'Supervisor':name}</h2></div>${tag('Draft available','amber')}</div>${tabButtons(['Overview','Chain','Instructions & skills','Tools','Context','Versions'],tab,'data-agent-tab')}${body}`;
}
function agentPage(){return heading('SPECIALISTS','Agents','Define how each specialist works. Compose procedures, constrain tools and publish versions.','<button data-action="external-agent">Connect external agent</button>')+(state.scenario==='empty'?emptyView('Start with the seven built-in specialists','Each specialist has a bounded responsibility and a versioned procedure.','config'):`<div class="split"><div class="list-panel">${agents.map(a=>`<button class="agent-row" data-agent="${a[0]}" aria-pressed="${state.agent===a[0]}"><span class="avatar">${a[2]}</span><span>${a[0]==='Manager'?'Supervisor':a[0]}<small>${a[1]}</small></span></button>`).join('')}<div style="padding:16px 10px;border-top:1px solid var(--line)"><div class="eyebrow">EXTERNAL AGENTS</div><button class="agent-row" data-action="external-agent"><span class="avatar">EX</span><span>Review partner<small>A2A · connection not verified</small></span></button></div></div><section class="panel" aria-label="Agent details">${agentContent()}</section></div>`);}
function tools(){const connections=[['Repository tools','INTERNAL','Read and edit an isolated source snapshot.','Available','No external credential'],['GitHub','DIRECT API','Read repositories and publish authorized draft PRs.','Available','Configured'],['Research server','MCP','Discover approved external research tools.','Not checked','Not configured'],['Review partner','A2A','Delegate a task and recover its remote status.','Not checked','Not configured'],['SABRE endpoint','MCP + A2A','Let a trusted client delegate work to this factory.','Local only','Client authorization required'],['Slack','NOTIFICATIONS','Deliver questions and milestones to the linked owner.','Not checked','Not configured']];return heading('CAPABILITIES & ACCESS','Tools','Connection, credentials and permission are separate checks. Discovery never grants execution access.','<button class="primary" data-action="connect-tool">Add connection</button>')+(state.scenario==='empty'?emptyView('No external connections','Built-in tools remain available. Add only the services your agents need.','agents'):`<div class="three-col">${connections.map(([name,type,description,available,credential])=>`<article class="connection"><div class="section-head">${tag(type)}${tag(state.disabledTools.has(name)?'Disabled':available,available==='Available'?'green':'')}</div><h3>${name}</h3><p>${description}</p><dl class="kv"><dt>Credential</dt><dd>${credential}</dd><dt>Agent access</dt><dd>${name==='Repository tools'?'Role-scoped':'Explicit allowlist'}</dd><dt>Project access</dt><dd>${name==='GitHub'?'checkout-service':'Not granted globally'}</dd></dl><div class="actions"><button data-connection="${name}">Inspect</button><button data-disable="${name}">${state.disabledTools.has(name)?'Enable':'Disable'}</button></div></article>`).join('')}</div><div class="panel" id="tool-details" hidden style="margin-top:20px"></div>`);}
function memory(){const rows=state.memory==='Proposals'?[['Retry policy recommendation','Inference','PM · run 039','Needs validation'],['Consider a schema migration','Inference','Developer · run 038','Needs validation']]:state.memory==='Sources'?[['src/checkout.ts','Source','Commit 8f20c1e','Current'],['package-lock.json','Dependency manifest','Commit 8f20c1e','Current'],['README.md','Documentation','Commit 8f20c1e','Current']]:state.memory==='Relations'?[['checkout.ts → checkout.test.ts','Evidence link','Verified file references','Current'],['Run 041 → regression finding','Run provenance','Recorded check result','Current']]:[['Empty input regression reproduced','Verified fact','QA · run 041 · commit 724cd8a','Historical'],['Registered suite: node --test','Repository fact','package.json · commit 8f20c1e','Current'],['Checkout validation is synchronous','Source observation','src/checkout.ts:18 · commit 8f20c1e','Current']];return heading('PROJECT KNOWLEDGE','Memory','Inspect what is known, where it came from and what an agent actually received.',`<label class="field">Project<select><option>checkout-service</option></select></label>`)+(state.scenario==='empty'?emptyView('No repository has been indexed','Connect a repository to capture its commit, index relevant source files and build a provenance map.','config'):`<div class="metrics"><div class="metric"><span>Indexed files</span><strong>128</strong></div><div class="metric"><span>Verified facts</span><strong>18</strong></div><div class="metric"><span>Pending proposals</span><strong>2</strong></div><div class="metric"><span>Current source</span><strong class="mono">8f20c1e</strong></div><div class="metric"><span>Last retrieval</span><strong>4 items</strong></div></div>${tabButtons(['Facts','Sources','Proposals','Relations','Context'],state.memory,'data-memory')}${state.memory==='Context'?`<div class="two-col"><section class="panel"><h2>What Developer received</h2><p>Task-specific excerpts, not the entire repository.</p><ul class="checklist"><li>Source excerpts <span>3 files · 8.2 KiB</span></li><li>Verified memory <span>4 items · 4.6 KiB</span></li><li>Source commit <code>8f20c1e</code></li><li>Compaction <span>References retained</span></li></ul></section><section class="panel"><h2>Why these items?</h2><p>They match the checkout task and its source snapshot. Older observations are excluded unless marked historical.</p><p>Retrieval is evidence of context use, not proof of improved model performance.</p></section></div>`:`<div class="table-wrap"><table><thead><tr><th>KNOWLEDGE</th><th>TYPE</th><th>PROVENANCE</th><th>VALIDITY</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${tag(r[3],r[3]==='Current'?'green':'amber')}</td><td><button data-memory-item="${i}">Inspect</button></td></tr>`).join('')}</tbody></table></div><section id="memory-details" class="panel memory-evidence" hidden></section>`}<details class="panel" style="margin-top:20px"><summary>Storage and retrieval</summary><p style="margin-top:15px">PostgreSQL stores facts and provenance. Lexical search is available; vector retrieval requires an embedding provider. Relationship views use stored references, not a separate graph database. Cache entries are not learned facts.</p></details>`);}
function configObject(){return {version:2,model:{provider:state.provider,name:state.model},flow:'patch',limits:{max_calls:40,max_tokens:100000,repair_cycles:2},permissions:{draft_pull_request:true,release:false}};}
function config(){const step=state.configStep;return heading('FACTORY SETTINGS','Config','A guided setup for the essentials. One validated contract behind the form and configuration file.',tag('Local instance'))+`<div class="subnav"><button data-config-mode="Guided" aria-pressed="${state.configMode==='Guided'}">Guided setup</button><button data-config-mode="YAML" aria-pressed="${state.configMode==='YAML'}">YAML / JSON</button><button data-config-mode="Policies" aria-pressed="${state.configMode==='Policies'}">Policies & limits</button></div>`+(state.configMode==='YAML'?`<section class="panel"><h2>Configuration contract</h2><p>JSON is also valid YAML. This concept demonstrates one shared data model; the production parser will enforce the versioned schema.</p><label class="field">Configuration document<textarea id="config-document" rows="18" spellcheck="false">${escape(JSON.stringify(configObject(),null,2))}</textarea></label><div class="actions" style="margin-top:16px"><button class="primary" data-action="validate-config">Validate & preview</button><button data-action="export-config">Download example</button></div><div id="config-validation" style="margin-top:18px"></div><p class="footer-note">Prototype validation accepts JSON only. Full YAML validation is covered by the configuration spec.</p></section>`:state.configMode==='Policies'?policyConsole():`<div class="progress-steps">${['Connect provider','Choose model','Connect project','Review readiness'].map((s,i)=>`<button class="progress-step ${i<step?'done':i===step?'current':''}" data-config-step="${i}">${i<step?'✓':String(i+1).padStart(2,'0')} ${s}</button>`).join('')}</div><div class="two-col"><section class="panel"><div class="eyebrow">STEP ${step+1} OF 4</div>${step===0?providerConnectionForm():step===1?`<h2>Choose the default model</h2><p>Start with one model for the team. Override specialists later in Agents.</p><label class="field">Model identifier<input id="model-name" value="${escape(state.model)}" placeholder="Your provider's model identifier"><small>The prototype name is illustrative, not a recommended or verified model.</small></label><div class="notice" style="margin-top:20px">Provider: ${prototypeProvider().name}<br>Context will be sent to this provider. Changing the model does not increase budgets.</div><button class="primary" data-next="2">Continue to project</button>`:step===2?githubConnectionForm():`<h2>Review before launching</h2><p>Configuration is separate from execution. Saving never starts a run.</p><ul class="checklist"><li>Provider session ${tag('Connected','green')}</li><li>Model <code>${escape(state.model)}</code></li><li>Repository ${tag('Access checked','green')}</li><li>Verification <code>node --test</code></li><li>Delivery ${tag('Draft PR only','green')}</li></ul><label style="display:flex;gap:10px;align-items:flex-start;margin:20px 0;font-size:12px"><input id="approve-config" type="checkbox" style="width:auto" ${state.approved?'checked':''}>I approve these data destinations and permissions for this example configuration.</label><button class="primary" data-action="save-config" ${state.approved?'':'disabled'}>Save example configuration</button>`}</section><aside class="panel"><div class="eyebrow">EFFECTIVE CONFIGURATION</div><h2>What the factory will use</h2><dl class="kv"><dt>Provider</dt><dd>${prototypeProvider().name}</dd><dt>Model</dt><dd>${escape(state.model)||'Not selected'}</dd><dt>Team</dt><dd>7 specialists · inherited default</dd><dt>Context</dt><dd>Project-scoped retrieval</dd><dt>Routing</dt><dd>Registered rules · no extra model</dd><dt>Permissions</dt><dd>Draft PR · no merge or release</dd></dl><details><summary>View effective JSON</summary>${json(configObject())}</details><p class="footer-note">Credentials never appear in configuration exports. All values here are examples.</p></aside></div>`);}
function render(){state.route=location.hash.slice(1)||'runs';if(!['runs','agents','tools','memory','config'].includes(state.route))state.route='runs';$('#breadcrumb').textContent=state.route[0].toUpperCase()+state.route.slice(1);document.querySelectorAll('[data-route]').forEach(a=>a.setAttribute('aria-current',a.dataset.route===state.route?'page':'false'));const banner=$('#connection-banner');banner.hidden=!['error','offline'].includes(state.scenario);banner.className=`banner ${state.scenario==='error'?'error':''}`;banner.textContent=state.scenario==='offline'?'Disconnected — showing the last synthetic snapshot. Run controls are unavailable until reconnection.': 'Connection check failed — the factory could not confirm the provider status. No retry or provider switch has been performed.';$('#main').innerHTML=({runs,agents:agentPage,tools,memory,config}[state.route])();if(state.scenario==='offline')$('#main').querySelectorAll('button,input,textarea,select').forEach(el=>el.disabled=true);}
function connectionDetails(name){const panel=$('#tool-details');panel.hidden=false;panel.innerHTML=`<div class="section-head"><h2>${escape(name)}</h2>${tag('Example connection')}</div><p>Inspect capabilities before granting access. A successful connection test does not authorize tool execution.</p><ul class="checklist"><li>Transport <span>${name==='Review partner'?'A2A · official protocol':name==='SABRE endpoint'?'Local MCP / A2A':'Registered adapter'}</span></li><li>Credential <span>Write-only reference · never exported</span></li><li>Allowed projects <span>Explicit selection required</span></li><li>Uncertain effects <span>Reconcile before retrying</span></li></ul><button data-action="test-connection" style="margin-top:16px">Test example connection</button>`;panel.scrollIntoView({behavior:'auto',block:'nearest'});}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||button.disabled)return;const d=button.dataset;
  if(d.node){state.node=d.node;render();return;}if(d.inspector){state.inspector=d.inspector;render();return;}if(d.agent){state.agent=d.agent;render();return;}if(d.agentTab){state.agentTab=d.agentTab;render();return;}if(d.memory){state.memory=d.memory;render();return;}if(d.configMode){state.configMode=d.configMode;render();return;}if(d.configStep!==undefined){state.configStep=Number(d.configStep);render();return;}
  if(d.next){if($('#model-name')){const name=$('#model-name').value.trim();if(!name){toast('Choose a model identifier before continuing.');$('#model-name').focus();return;}state.model=name;}state.configStep=Number(d.next);render();return;}
  if(d.connection){connectionDetails(d.connection);return;}if(d.disable){state.disabledTools.has(d.disable)?state.disabledTools.delete(d.disable):state.disabledTools.add(d.disable);render();toast('Example permission updated. No live connection changed.');return;}
  if(d.memoryItem!==undefined){const panel=$('#memory-details');panel.hidden=false;panel.innerHTML=`<h2>Provenance and validity</h2>${json({id:`example-memory-${d.memoryItem}`,project:'checkout-service',source_commit:'8f20c1e',kind:state.memory==='Proposals'?'inference':'source_reference',status:state.memory==='Proposals'?'proposed':'recorded',source:'synthetic fixture',permissions:'context only'})}<p>Memories are untrusted context, not instructions or permissions. A changed source commit requires revalidation.</p>`;return;}
  switch(d.action){case'pause':state.run=state.run==='paused'?'running':'paused';render();toast('Synthetic run state changed.');break;case'new-run':location.hash='config';break;case'question':state.run='waiting_input';render();break;case'answer-empty':case'answer-error':state.run='running';render();toast('Example answer recorded against the current question revision.');break;case'delivery':state.node='delivery';state.inspector='Evidence';render();toast('Delivery preview only. No checks have completed and no PR was published.');break;case'draft':toast('Example draft saved in this view. Published versions are unchanged.');break;case'publish-agent':toast('Version preview: v3 → v4. Only the acceptance handoff instruction changes; permissions are unchanged.');break;case'external-agent':location.hash='tools';toast('External agents connect through MCP tools or A2A delegation.');break;case'connect-tool':toast('Prototype: choose an MCP endpoint, registered API adapter or A2A Agent Card. Do not enter real credentials.');break;case'test-connection':toast('Synthetic diagnostic: endpoint reachable; authorization still required.');break;case'save-config':if(state.approved){toast('Example configuration saved. No run has started.');state.notification=true;}break;case'export-config':{const link=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(configObject(),null,2)],{type:'application/json'}));link.href=url;link.download='sabre-example.json';link.click();URL.revokeObjectURL(url);break;}case'validate-config':{const panel=$('#config-validation');try{const next=JSON.parse($('#config-document').value);if(next.version!==2||typeof next.model?.name!=='string'||!next.model.name.trim())throw Error();panel.innerHTML=`<div class="notice">Example structure accepted. This is a preview, not production schema validation.</div><h3>Proposed configuration</h3>${json(next)}`;}catch{panel.innerHTML='<div class="notice error" role="alert">This prototype expects JSON with version 2 and a non-empty model.name. Nothing was saved.</div>';}break;}}
});
document.addEventListener('change',event=>{if(event.target.id==='scenario'){state.scenario=event.target.value;render();}if(event.target.id==='approve-config'){state.approved=event.target.checked;const button=$('[data-action="save-config"]');button.disabled=!state.approved;}if(event.target.id==='provider-choice'){state.provider=event.target.value;state.model='';state.approved=false;render();$('#provider-choice').value=state.provider;}});
window.addEventListener('hashchange',render);render();
